//! Parity tests for `meerschaum_connector_sql::uri` against `tests/fixtures/uris.json`
//! (generated by `tests/fixtures/gen_uris.py` from the Python implementation).

use indexmap::IndexMap;
use meerschaum_connector_sql::Flavor;
use meerschaum_connector_sql::uri::{
    ConnectionOptions, ConnectionSpec, ConnectorAttributes, UriValue, from_uri_params, parse_uri,
};
use serde_json::Value;

fn fixtures() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/uris.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn py_str(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        other => other.to_string(),
    }
}

/// Compare a Python dict (as JSON) with a Rust map of strings, ignoring key order.
fn assert_same_map(case: &str, expected: &Value, actual: &IndexMap<String, String>) {
    let expected = expected.as_object().expect("dict");
    let mut exp: Vec<(String, String)> = expected
        .iter()
        .map(|(k, v)| (k.clone(), py_str(v)))
        .collect();
    let mut act: Vec<(String, String)> =
        actual.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
    exp.sort();
    act.sort();
    assert_eq!(act, exp, "attributes mismatch for {case}");
}

/// Ordered comparison (Python dict insertion order is part of the contract for `parse_uri`).
fn assert_ordered(case: &str, expected: &Value, actual: &IndexMap<String, UriValue>) {
    let exp: Vec<(String, String)> = expected
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), py_str(v)))
        .collect();
    let act: Vec<(String, String)> = actual
        .iter()
        .map(|(k, v)| (k.clone(), v.as_string()))
        .collect();
    // serde_json (without `preserve_order`) sorts object keys, so compare sorted when needed.
    let mut exp_sorted = exp.clone();
    let mut act_sorted = act.clone();
    exp_sorted.sort();
    act_sorted.sort();
    assert_eq!(act_sorted, exp_sorted, "{case}");
    for (k, v) in actual {
        if let UriValue::Int(_) = v {
            assert!(
                expected[k].is_number(),
                "{case}: '{k}' should be an int in Python"
            );
        }
    }
}

#[test]
fn parse_uri_parity() {
    let fx = fixtures();
    let mut checked = 0;
    for case in fx["uris"].as_array().unwrap() {
        let uri = case["uri"].as_str().unwrap();
        let rust = parse_uri(uri);
        match (&case["parse_uri"].get("ok"), rust) {
            (Some(expected), Ok(actual)) => assert_ordered(uri, expected, &actual),
            (None, Err(_)) => {}
            (Some(_), Err(e)) => panic!("{uri}: Python parsed, Rust failed: {e}"),
            (None, Ok(actual)) => panic!("{uri}: Python failed, Rust parsed {actual:?}"),
        }
        checked += 1;
    }
    assert!(checked >= 25);
}

#[test]
fn from_uri_parity() {
    let fx = fixtures();
    for case in fx["uris"].as_array().unwrap() {
        let uri = case["uri"].as_str().unwrap();
        let rust = from_uri_params(uri, None);
        match (&case["from_uri"].get("ok"), rust) {
            (Some(expected), Ok(actual)) => assert_ordered(uri, expected, &actual),
            (None, Err(_)) => {}
            (Some(_), Err(e)) => panic!("{uri}: Python parsed, Rust failed: {e}"),
            (None, Ok(actual)) => panic!("{uri}: Python failed, Rust parsed {actual:?}"),
        }
    }
}

#[test]
fn connector_from_uri_parity() {
    let fx = fixtures();
    for case in fx["uris"].as_array().unwrap() {
        let uri = case["uri"].as_str().unwrap();
        let rust = ConnectionSpec::from_uri(uri, None, None);
        match (&case["connector"].get("ok"), rust) {
            (Some(expected), Ok(spec)) => {
                assert_same_map(uri, &expected["attributes"], &spec.attributes());
                assert_eq!(
                    spec.engine_str().unwrap(),
                    expected["engine_str"].as_str().unwrap(),
                    "engine_str for {uri}"
                );
            }
            (None, Err(_)) => {}
            (Some(_), Err(e)) => panic!("{uri}: Python built a connector, Rust failed: {e}"),
            (None, Ok(spec)) => panic!("{uri}: Python failed, Rust built {spec:?}"),
        }
    }
}

fn attrs_from_case(case: &Value) -> ConnectorAttributes {
    let mut attrs = ConnectorAttributes {
        label: Some(case["label"].as_str().unwrap().to_string()),
        flavor: Some(case["flavor"].as_str().unwrap().parse::<Flavor>().unwrap()),
        ..Default::default()
    };
    for (k, v) in case["attributes"].as_object().unwrap() {
        match k.as_str() {
            "uri" => attrs.uri = Some(py_str(v)),
            "host" => attrs.host = Some(py_str(v)),
            "port" => attrs.port = Some(v.as_u64().unwrap() as u16),
            "username" => attrs.username = Some(py_str(v)),
            "password" => attrs.password = Some(py_str(v)),
            "database" => attrs.database = Some(py_str(v)),
            "schema" => attrs.schema = Some(py_str(v)),
            "options" => {
                attrs.options = Some(match v {
                    Value::String(s) => ConnectionOptions::Str(s.clone()),
                    Value::Object(o) => ConnectionOptions::Pairs(
                        o.iter().map(|(k, v)| (k.clone(), py_str(v))).collect(),
                    ),
                    other => panic!("unexpected options {other}"),
                })
            }
            other => attrs.extra.push((other.to_string(), py_str(v))),
        }
    }
    attrs
}

#[test]
fn connector_from_attributes_parity() {
    let fx = fixtures();
    for case in fx["attributes"].as_array().unwrap() {
        let label = case["label"].as_str().unwrap();
        let attrs = attrs_from_case(case);
        let rust = ConnectionSpec::from_attributes(&attrs);
        match (&case["connector"].get("ok"), rust) {
            (Some(expected), Ok(spec)) => {
                let mut exp_attrs = expected["attributes"].clone();
                // `options` may be a dict in Python; compare it through the engine string only.
                if exp_attrs["options"].is_object() {
                    exp_attrs.as_object_mut().unwrap().remove("options");
                }
                let mut actual = spec.attributes();
                if matches!(spec.options, Some(ConnectionOptions::Pairs(_))) {
                    actual.shift_remove("options");
                }
                assert_same_map(label, &exp_attrs, &actual);
                assert_eq!(
                    spec.engine_str().unwrap(),
                    expected["engine_str"].as_str().unwrap(),
                    "engine_str for {label}"
                );
            }
            (None, Err(_)) => {}
            (Some(_), Err(e)) => panic!("{label}: Python built a connector, Rust failed: {e}"),
            (None, Ok(spec)) => panic!("{label}: Python failed, Rust built {spec:?}"),
        }
    }
}

#[test]
fn display_masks_password() {
    let spec = ConnectionSpec::from_uri(
        "postgresql://test:test1234@localhost:5559/testdb",
        None,
        None,
    )
    .unwrap();
    assert_eq!(
        spec.display_str(),
        "postgresql+psycopg://test:********@localhost:5559/testdb"
    );
}
